CREATE TYPE public.app_role AS ENUM ('field_team','validation_team','admin','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', team text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.create_gridtwin_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name',''),100)) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user') ON CONFLICT DO NOTHING; RETURN NEW; END; $$;
CREATE TRIGGER create_gridtwin_account AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_gridtwin_account();
INSERT INTO public.profiles(id,display_name) SELECT id,left(coalesce(raw_user_meta_data->>'full_name',raw_user_meta_data->>'name',''),100) FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'user'::public.app_role FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.app_settings (key text PRIMARY KEY, value text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.app_settings TO authenticated;
GRANT ALL ON public.app_settings TO service_role;
ALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.app_settings FOR SELECT TO authenticated USING(true);
CREATE POLICY settings_admin ON public.app_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.field_reports ADD COLUMN submitted_by uuid, ADD COLUMN submitted_team text, ADD COLUMN validated_by uuid;
ALTER TABLE public.proposals ADD COLUMN validated_by uuid;
DROP POLICY demo_layers ON public.layers;
DROP POLICY demo_proposals ON public.proposals;
DROP POLICY demo_scores ON public.line_scores;
DROP POLICY demo_reports ON public.field_reports;
DROP POLICY demo_audit_read ON public.audit_log;
DROP POLICY demo_audit_insert ON public.audit_log;
REVOKE ALL ON public.layers,public.proposals,public.line_scores,public.field_reports,public.audit_log FROM anon;
REVOKE INSERT,UPDATE,DELETE ON public.field_reports FROM authenticated;
GRANT SELECT ON public.field_reports TO authenticated;
CREATE POLICY layers_read ON public.layers FOR SELECT TO authenticated USING(true);
CREATE POLICY layers_admin ON public.layers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY proposals_read ON public.proposals FOR SELECT TO authenticated USING(true);
CREATE POLICY proposals_admin ON public.proposals FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY scores_read ON public.line_scores FOR SELECT TO authenticated USING(true);
CREATE POLICY scores_admin ON public.line_scores FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY reports_read ON public.field_reports FOR SELECT TO authenticated USING(true);
CREATE POLICY audit_read ON public.audit_log FOR SELECT TO authenticated USING(true);
CREATE POLICY audit_insert ON public.audit_log FOR INSERT TO authenticated WITH CHECK((public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'validation_team')) AND actor=(SELECT display_name FROM public.profiles WHERE id=auth.uid()));
DROP POLICY demo_field_photo_read ON storage.objects;
DROP POLICY demo_field_photo_insert ON storage.objects;
CREATE POLICY field_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='field-photos');
CREATE POLICY field_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='field-photos' AND (public.has_role(auth.uid(),'field_team') OR public.has_role(auth.uid(),'admin')));
CREATE FUNCTION public.gridtwin_actor() RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE n text; t text; BEGIN SELECT display_name,team INTO n,t FROM public.profiles WHERE id=auth.uid(); IF auth.uid() IS NULL OR length(trim(coalesce(n,'')))<2 OR length(trim(coalesce(t,'')))<2 THEN RAISE EXCEPTION 'Completează numele și echipa contului'; END IF; RETURN n; END; $$;
CREATE OR REPLACE FUNCTION public.submit_field_report(report jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; actor_name text; BEGIN IF NOT (public.has_role(auth.uid(),'field_team') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Acces interzis: Field team'; END IF; actor_name:=public.gridtwin_actor(); IF report->>'photo_pole_url' IS NULL OR report->>'photo_sheet_url' IS NULL OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='field-photos' AND name=report->>'photo_pole_url' AND owner_id=auth.uid()::text) OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='field-photos' AND name=report->>'photo_sheet_url' AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Fotografii lipsă sau aparțin altui cont'; END IF; INSERT INTO public.field_reports(actor,submitted_by,submitted_team,lat,lon,pos_source,fields,pole_check,photo_pole_url,photo_sheet_url) VALUES(actor_name,auth.uid(),(SELECT team FROM public.profiles WHERE id=auth.uid()),(report->>'lat')::double precision,(report->>'lon')::double precision,report->>'pos_source',report->'fields',report->'pole_check',report->>'photo_pole_url',report->>'photo_sheet_url') RETURNING id INTO rid; INSERT INTO public.audit_log(actor,text) VALUES(actor_name,'Raport din teren trimis · '||rid); RETURN rid; END; $$;
CREATE OR REPLACE FUNCTION public.submit_osm_inspection(report jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; geom jsonb; actor_name text; BEGIN IF NOT (public.has_role(auth.uid(),'field_team') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Acces interzis: Field team'; END IF; actor_name:=public.gridtwin_actor(); IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='field-photos' AND name=report->>'photo_pole_url' AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Fotografie lipsă sau aparține altui cont'; END IF; SELECT f->'geometry' INTO geom FROM public.layers l,jsonb_array_elements(l.geojson->'features') f WHERE l.name='osm_constanta' AND f->'properties'->>'osm_id'=report->>'osm_id' LIMIT 1; IF geom IS NULL THEN RAISE EXCEPTION 'Element OSM absent din importul curent'; END IF; INSERT INTO public.field_reports(actor,submitted_by,submitted_team,lat,lon,pos_source,fields,photo_pole_url,osm_id,osm_verdict,evidence_notes,inspected_at,osm_geometry) VALUES(actor_name,auth.uid(),(SELECT team FROM public.profiles WHERE id=auth.uid()),(report->>'lat')::double precision,(report->>'lon')::double precision,report->>'pos_source','{}',report->>'photo_pole_url',report->>'osm_id',report->>'osm_verdict',report->>'evidence_notes',now(),geom) RETURNING id INTO rid; INSERT INTO public.audit_log(actor,text) VALUES(actor_name,'Verificare OSM trimisă · '||(report->>'osm_id')||' · '||rid); RETURN rid; END; $$;
CREATE OR REPLACE FUNCTION public.decide_grid_item(item_id text,item_kind text,decision text,operator_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_osm text; verdict text; actor_name text; BEGIN IF NOT(public.has_role(auth.uid(),'validation_team') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Acces interzis: Validation team'; END IF; actor_name:=public.gridtwin_actor(); IF decision NOT IN ('aprobat','respins','in_asteptare') THEN RAISE EXCEPTION 'Decizie invalidă'; END IF; IF item_kind='proposal' THEN UPDATE public.proposals SET status=decision,decided_by=CASE WHEN decision='in_asteptare' THEN NULL ELSE actor_name END,validated_by=CASE WHEN decision='in_asteptare' THEN NULL ELSE auth.uid() END,decided_at=CASE WHEN decision='in_asteptare' THEN NULL ELSE now() END WHERE id=item_id; ELSIF item_kind='field' THEN UPDATE public.field_reports SET status=decision,decided_by=CASE WHEN decision='in_asteptare' THEN NULL ELSE actor_name END,validated_by=CASE WHEN decision='in_asteptare' THEN NULL ELSE auth.uid() END,decided_at=CASE WHEN decision='in_asteptare' THEN NULL ELSE now() END WHERE id=item_id::uuid RETURNING osm_id,osm_verdict INTO target_osm,verdict; ELSE RAISE EXCEPTION 'Tip invalid'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Înregistrare inexistentă'; END IF; INSERT INTO public.audit_log(actor,text) VALUES(actor_name,CASE decision WHEN 'aprobat' THEN 'Aprobat' WHEN 'respins' THEN 'Respins' ELSE 'Decizie anulată pentru' END||' '||item_id||CASE WHEN target_osm IS NOT NULL THEN ' · OSM '||target_osm||' · '||verdict ELSE '' END); END; $$;
REVOKE EXECUTE ON FUNCTION public.submit_field_report(jsonb),public.submit_osm_inspection(jsonb),public.decide_grid_item(text,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_field_report(jsonb),public.submit_osm_inspection(jsonb),public.decide_grid_item(text,text,text,text) TO authenticated;
CREATE FUNCTION public.set_gridtwin_role(target_user uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(183710); IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acces interzis: admin'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target_user) THEN RAISE EXCEPTION 'Cont inexistent'; END IF; IF public.has_role(target_user,'admin') AND new_role<>'admin' AND (SELECT count(*) FROM public.user_roles WHERE role='admin')<=1 THEN RAISE EXCEPTION 'Ultimul administrator nu poate fi eliminat'; END IF; DELETE FROM public.user_roles WHERE user_id=target_user; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,new_role); INSERT INTO public.audit_log(actor,text) VALUES(public.gridtwin_actor(),'Rol actualizat · '||target_user||' · '||new_role); END; $$;
REVOKE EXECUTE ON FUNCTION public.set_gridtwin_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_gridtwin_role(uuid,public.app_role) TO authenticated;
COMMENT ON FUNCTION public.submit_osm_inspection(jsonb) IS 'Authenticated field-team submission with verified identity and owned photo; immutable evidence snapshot.';